"""Assess fresh executions without promoting supplemental controls to open gates."""
import pathlib,json,re,hashlib,subprocess
R=pathlib.Path(__file__).resolve().parents[5];E=pathlib.Path(__file__).resolve().parent

def read(p):return json.loads((E/p).read_text())
def write(p,x):(E/p).write_text(json.dumps(x,indent=2)+'\n')
def digest(p):return hashlib.sha256(p.read_bytes()).hexdigest()
baseline=read('source-baseline.json')
changed=[p for p,h in baseline['files'].items() if not (R/p).is_file() or digest(R/p)!=h]
links=[p for p,t in baseline['symlinks'].items() if not (R/p).is_symlink() or str((R/p).readlink())!=t]
assert not changed and not links,(changed,links)
rows=read('executions.json');extra=read('extra-executions.json');ipc_exec=read('ipc-v2-executions.json')
assert len(ipc_exec)==3
all_exec=rows+extra
matrix=[];lifecycle=[];ipc=[]
for cpu in [1,2,4]:
 life=read(f'lifecycle-cpu-{cpu}/results.json');reg=read(f'regression-cpu-{cpu}/results.json');tls=read(f'tls-cpu-{cpu}/results.json');supp=read(f'supplemental-cpu-{cpu}/results.json')
 assert len(life)==17 and len(reg)==94 and len(tls)==4 and len(supp)==2
 cxx={n:x for n,x in reg.items() if n.startswith(('cxx-','cpp-'))};c={n:x for n,x in reg.items() if n not in cxx}
 assert len(c)==73 and len(cxx)==21
 serial=(E/f'lifecycle-cpu-{cpu}/serial.log').read_text()
 for i,(name,x) in enumerate(life.items()):
  owner=100+i;terminal=re.findall(rf'^\[NATIVE-GROUP\] terminal pid={owner} incarnation=(\d+) vm=(\d+) code=(\d+) reason=(.+)$',serial,re.M)
  quiescent=re.findall(rf'^\[NATIVE-GROUP-WITNESS\] owner={owner} incarnation=(\d+) vm=(\d+) worker=(\d+) wi=(\d+) owner_finished=1 quiescent=1 group_live=1 cpu=(\d+)$',serial,re.M)
  needed=re.findall(r'W progress actor=\d+ tid=(\d+) after-owner-query',x['stdout'])
  observed={v[2] for v in quiescent}
  semantic=x['pass_'] and len(terminal)==1 and all(t in observed for t in needed)
  assert semantic,(cpu,name)
  lifecycle.append(dict(cpu=cpu,case=name,status='PASS',terminal_receipts=terminal,quiescent_worker_receipts=quiescent,workers_observed_before_progress=needed,source_manifest='source-baseline.json',evidence=f'lifecycle-cpu-{cpu}/',overlap='NOT_RUN',scope='Existing lifecycle control; terminal log count does not prove independent race arbitration'))
 ip=read(f'ipc-v2-cpu-{cpu}/results.json')['ipc-continuity'];text=(E/f'ipc-v2-cpu-{cpu}/serial.log').read_text()
 witnesses=re.findall(r'^\[NATIVE-GROUP-WITNESS\].*$',text,re.M)
 required=['R2B5 IPC round=0 actor=0 PASS','R2B5 IPC round=0 actor=1 PASS','R2B5 IPC round=1 actor=0 PASS','R2B5 IPC round=1 actor=1 PASS','R2B5 peer endpoint authority denied','R2B5 PASS IPC continuity authority closure stale-token successor preserved']
 assert ip['pass_'] and all(m in ip['stdout'] for m in required)
 assert len(witnesses)==2 and all('quiescent=1' in w for w in witnesses)
 assert text.count('[NATIVE-GROUP] terminal ')==1 and '[NATIVE-C-REAP-END] case=0 exit=0' in text
 ipc.append(dict(cpu=cpu,status='PASS',scope='Legacy task-owned IPC endpoint, same-VM borrowers, no authenticated account/channel/session',identities=witnesses,endpoints=re.findall(r'^\[CAP\] Created endpoint.*$',text,re.M),terminal=re.findall(r'^\[NATIVE-GROUP\] terminal.*$',text,re.M),accounting=re.findall(r'^\[NATIVE-C-(?:REAP-END|RESULT)\].*$',text,re.M),coordinator='User-space release/acquire rendezvous; pre/post RPCs; endpoint-owner Reaped acknowledgment before stale-token checks',observed_overlap=False,evidence=f'ipc-v2-cpu-{cpu}/',source='source-baseline.json',elf=read('ipc-v2-cases.json')[0]['elf'],elf_sha256=digest(pathlib.Path(read('ipc-v2-cases.json')[0]['elf']))))
 matrix.append(dict(cpus=cpu,lifecycle=f"{sum(x['pass_'] for x in life.values())}/17",C=f"{sum(x['pass_'] for x in c.values())}/73",CXX=f"{sum(x['pass_'] for x in cxx.values())}/21",tls_once=f"{sum(x['pass_'] for x in tls.values())}/4",heap_abi='PASS' if supp['heap-abi']['pass_'] else 'FAIL',retained_admission='PASS' if supp['retained-admission']['pass_'] else 'FAIL',legacy_IPC='PASS',W6='UNQUALIFIED',authenticated_IPC='NOT_RUN',borrower_SHM='BLOCKED',integrated_faults='NOT_RUN',PTY='NOT_RUN',generation_reuse='NOT_RUN',tcp='PASS' if cpu in [2,4] else 'NOT_RUN',source='source-baseline.json'))
write('cpu-matrix.json',dict(status='PARTIAL',rows=matrix,cpus12='NOT_RUN: native guest runner choices are 1/2/4; TCP choices 2/4',source='source-baseline.json'))
