write('borrower-shm-lifetime.json',dict(status='BLOCKED',attempts=negative,root_cause='native_c_guest launch grants system_allocation only for network fixtures; ordinary cases have no account_membership. alloc_shared_region rejects !system_allocation when no account session exists. thread_spawn preserves these fields. This is policy rejection, not a demonstrated lifetime defect.',source_references=['kernel/src/native_c_guest.rs:152','kernel/src/arch/x86_64/syscall.rs:2910','kernel/src/memory/shared.rs:89'],VM_model='One address-space root/generation and shared generation-qualified region ledger per group. Explicit maps would create distinct VAs/views in that same VM; mapped_shared and owned_shared vectors are task-local. No successful views were created in these attempts.',mapping_identity='VM root/generation + VA/extent + MappingRegion kind/backing; per-task mapped_shared includes token/base/size',not_run=['Authorized post-owner allocation','Peer read/write and two-view publication','Creator exit with peer retained view','Last-view backing release and quota refund','Revocation and concurrent retirement','Forced termination with allocated backing'],production_changes=[]))
retire=read('retirement-controls/guest-results.json')
write('retirement-faults.json',dict(status='UNQUALIFIED',group_integrated={n:'NOT_RUN' for n in ['shootdown uncertainty','interrupted retirement','partial SHM unmap','cleanup versus final exit','concurrent revocation','backing after last view']},standalone_controls=retire,scope='Existing 2-CPU synthetic VM/retirement controls, not the borrower SHM workload',policy='Retain exact retirement owner, backing and quota on uncertainty; fail stop/quarantine. Timeout or process disappearance cannot qualify reclamation.',source_references=['kernel/src/memory/retirement.rs','kernel/src/memory/tlb.rs','kernel/src/memory/shared.rs:367','kernel/src/process/address_space.rs:1696']))
