write('session-pty-witnesses.json',dict(status='NOT_RUN',native_scenarios={n:'NOT_RUN' for n in ['owner exit + surviving PTY I/O','foreground membership','final borrower cleanup','forced group termination','terminal tab close','stale session generation']},supplemental={'pty_host':'PASS 11/11, pty-host-corrected.log','foreground_host':'PASS 8/8, foreground-host.log'},runner_limitation='tools/native-c/guest.py headless nonnetwork batch starts captured-VFS-stream cases, without pty_server, terminal tabs, trusted foreground binding or authenticated session. tools/test_pty_liveness.py runs existing shell stream gates but has no retained-owner borrower scenario. No integrated terminal/session runner was added.',failed_attempt='pty-host.log used missing pty_server/Cargo.toml; corrected services/pty_server/Cargo.toml is separate',authority='Exact broker publication/session/generation and caller role capabilities; borrower publication clears session_owner and foreground owned scope',source_references=['docs/terminal/per-tab-session-lifecycle.md','kernel/src/process/foreground.rs:142','kernel/src/sched/thread_admission.rs:139']))
write('identity-reuse.json',dict(status='PARTIAL',native_churn='Ten existing two-borrower lifecycle groups per CPU in lifecycle-cpu-*/; real scheduler borrower slot reuse and distinct VM generations recorded in serial logs',legacy_endpoint_stale_token='PASS 1/2/4: old closed token rejected while fresh endpoint remains usable; no numeric endpoint ID reuse asserted',group_generation_stale_kill='NOT_RUN: generation-qualified kill extension requires active manager; ordinary numeric kill is not a stale-generation witness',resource_limits='Runner independently measures RamFsFileData, UserPrivate, PageTable frame classes, VFS handles and temporary names; owner PMM frames=0, fds=0, stack=0 at reap. No integrated SHM, group-record/heap, endpoint/capability/session census or exact refund counts.',missing=['Generation-qualified operation against a reused process/group identity','Integrated borrower-created SHM/session churn','Bounded full resource inventory and cleanup-owner transition counters'],evidence=['lifecycle-witnesses.json','ipc-capability-continuity.json']))
security_names={'kernel-host','ipc-host','scheduler-host','production-check','foreground-host'}
write('security-regressions.json',dict(status='PARTIAL',executions=[x for x in all_exec if x['name'] in security_names],pty_host=dict(status='PASS',tests=11,evidence='pty-host-corrected.log'),native_IPC='ipc-capability-continuity.json',retirement='retirement-faults.json',findings=['No confirmed production defect established by these executions','Terminal receipt is published before nested termination and endpoint callbacks under SCHEDULER','Physical owner reclaim waits for borrower Reaped, stack pins/current/queue/core references and VM activity to clear','Numeric kill/reaped/endpoint-owner IDs are not universally generation-qualified; manager kill validates VM generation and manager authority','Same-VM membership does not authorize owner-only endpoint operations or exclusive restricted channels','SHM backing/quota final release follows actual view unmap and synchronous invalidation in source; integrated fault witness absent'],open=['W6 independently observed contention and one cleanup winner','Group-integrated SHM failure/revocation/refunds','Real PTY/tab teardown','Process/session/channel stale-generation reuse'],production_changes=[]))
write('native-regressions.json',dict(status='PASS' if all(x['exit']==0 and x.get('source_matches',True) for x in rows) and all(v.endswith('/17') and v.startswith('17') for v in [m['lifecycle'] for m in matrix]) else 'FAIL',matrix=matrix,executions=rows,supplemental=[x for x in extra if x['name'].startswith(('tls-','supplemental-','heap-','admission-','cxx-'))],scope='Fresh final production-source runtime/language/lifecycle/heap/TLS/TCP controls; security closure assessed separately',unsupported=['12 CPUs','TCP 1 CPU']))
