write('source-integrity.json',dict(status='PASS',revision=baseline['revision'],branch=baseline['branch'],files_checked=len(baseline['files']),symlinks_checked=len(baseline['symlinks']),changed_baseline_files=changed,changed_symlinks=links,production_changes=[],prior_evidence_preserved=True,source_manifest='source-baseline.json',command_boundary_checks='executions.json and extra-executions.json; full baseline comparison at final assessment',binding_limit='Installed-toolchain locked rebuild; no clean-room or bit-identical reproducibility claim. Per-guest ELF/kernel/log hashes and build commands retained.'))
